S('s-course', 'מפת הקורס', 'איפה אנחנו בקורס',
  '<div class="lmap">' + ''.join(f'<div class="{c}"><b>{TX(str(i))}</b>{TX(t)}</div>' for i, t, c in MAP) + '</div>'
  + '<div class="row eq2 top" style="margin-top:14px">'
  + '<div class="card"><b class="ct">במפגשים 1 ו-2</b><p class="lg">' + TX('ערך עתידי של סכום יחיד, ואחריו של סדרה: אותו סכום בכל תקופה. למדנו גם מה עושים כשהיעד מאוחר מההפקדה האחרונה, וכשהריבית משתנה באמצע.') + '</p></div>'
  + '<div class="card"><b class="ct">היום, מפגש 3</b><p class="lg">' + TX('משלימים את הכלים של הערך העתידי: מקטעים מסוגים שונים, השאלה ההפוכה (כמה להפקיד), וריבית שנתונה לתקופה אחרת מתקופת התשלום.') + '</p></div></div>'
  + BAND('note', 'הבחינה ב-Excel, ולכן גם היום כל שאלה נפתרת בגיליון חי שבתוך השקף. ״הצעד הבא״ ממלא תא אחד בכל לחיצה, ומסביר אותו.'), kick='לפני שמתחילים')

ROUTE = [(1, 'חיבור: מה כבר יודעים', 'המסע עד כאן, המהות, ושלושה חיזוקים', 'כ-25 דקות'),
         (2, 'מקטעים מורכבים', 'סוגים שונים של מקטעים, והפסקה באמצע', 'כ-40 דקות'),
         (3, 'חילוץ ההפקדה', 'היעד ידוע. כמה להפקיד? הפונקציה PMT', 'כ-30 דקות'),
         (4, 'התאמת ריבית', 'ריבית נקובה, ריבית אפקטיבית, ותקופת התשלום', 'כ-50 דקות'),
         (5, 'סיכום ותרגול בית', 'סיכומים, שאלות לבית ותרגיל מסכם', 'עבודה עצמית'),
         (6, 'תרגול עצמי', 'שאלות חדשות, אחרי שקף הסיום', 'תרגול עצמי'),
         (7, 'סיכום בזרימה', 'תהליכי העבודה בתרשימים', 'לחזרה')]
S('s-route', 'מסלול המפגש', 'מסלול המפגש',
  '<p class="lead">' + TX('שאלה אחת מלווה את השיעור: איך מפרקים כל חיסכון, מורכב ככל שיהיה, לעמודות פשוטות.' + (' לחצו על חלק כדי לעבור אליו.' if MODE == 'deck' else '')) + '</p><div class="route r7">'
  + ''.join(rcard(n, t, d, m, f'p-{n}') for n, t, d, m in ROUTE) + '</div>'
  + BAND('note', 'הדקות הן הערכה. השאלות של מחברת הקורס, ושאלות שמסומנות ״חדשה״ נכתבו לשיעור. קו מקווקו אדום: לחיצה פותחת הסבר נוסף.'), kick='לפני שמתחילים')

# ================================================================ part 1: the bridge
opener(1, 'חיבור: מה כבר יודעים, ומה חסר', 'שאלת החלק: מה משותף לכל שאלה שפתרנו עד היום?',
       ['המסע עד כאן: סכום יחיד, סדרה, והיום', 'המהות: כל עמודה מעבירה את המקל לבאה', 'שלושה חיזוקים קצרים, כל אחד עם גיליון', 'בדיקת הבנה אחת לפני שממשיכים'], 25,
       note='החלק הזה לא מלמד דבר חדש. הוא מסדר את מה שלמדנו בשני המפגשים, כדי שהחומר של היום יישב על בסיס יציב.')

_b1 = TL([0, '...', 'n'], flows={0: 'pv'}, marks={'n': 'FV'}, W=360, fs=18, fh=22)
_b2 = TL([0, 1, 2, '...', 'n'], flows={1: 'pmt', 2: 'pmt', 'n': 'pmt'}, W=360, fs=18, fh=22)
S('s-bridge', 'המסע עד כאן', 'המסע עד כאן: שני מפגשים, רעיון אחד',
  '<div class="bridge">'
  + ST(1, '<span class="when">מפגש 1</span><h5>סכום יחיד</h5>' + _b1 + '<ul><li>' + TX('מפקידים, או לווים, פעם אחת.') + '</li><li>' + TX('ריבית דריבית: גם הריבית צוברת ריבית.') + '</li><li>' + TX('ריבית משתנה: ') + MORE('שלב לכל ריבית', 'כשהריבית משתנה, מחשבים כל תקופה בעמודה משלה. ה-FV של העמודה הראשונה נכנס ל-pv של השנייה, בסימן הפוך. כך פתרנו את דניאל, את קורל ואת ולדי.') + '</li></ul>', cls='bst').replace('class="st bst"', 'class="st bst" style="--k:#0f9d90"')
  + ST(2, '<span class="when">מפגש 2</span><h5>סדרה</h5>' + _b2 + '<ul><li>' + TX('אותו סכום בכל תקופה: pmt.') + '</li><li>' + TX('nper סופר הפקדות, ו-rate הוא לתקופת תשלום.') + '</li><li>' + TX('ה-FV של סדרה ') + MORE('נוחת על ההפקדה האחרונה', 'ההפקדה האחרונה מגיעה ביום היעד, ולא צוברת ריבית. לכן FV של סדרה הוא הסכום בדיוק במועד ההפקדה האחרונה. כשהיעד מאוחר יותר, מוסיפים עמודה של צבירה בלבד: כך פתרנו את מקרנה סעיף ג.') + '</li></ul>', cls='bst').replace('class="st bst"', 'class="st bst" style="--k:#e8960c"')
  + ST(3, '<span class="when" style="background:#ff6a4d">היום</span><h5>משלימים את התמונה</h5><ul><li>' + TX('מקטעים מסוגים שונים, והפסקה באמצע.') + '</li><li>' + TX('השאלה ההפוכה: היעד ידוע, כמה להפקיד?') + '</li><li>' + TX('ריבית שנתונה לשנה, כשמפקידים בכל חודש.') + '</li></ul>', cls='bst now')
  + '</div>'
  + BAND('dg', 'הרעיון האחד: מביאים כל סכום, בריבית שלו, אל אותו מועד. רק אז מחברים.', 4), kick='חלק 1 · רענון')

S('s-core', 'המהות: חמש שורות', 'המהות: חמש שורות, ומקל שעובר',
  '<div class="row eq2 top"><div class="col">'
  + ST(1, TABLE(['שורה', 'מה כותבים', 'להרחבה'], [
      ['rate', 'הריבית לתקופה אחת', MORE('לאיזו תקופה?', 'כשיש הפקדות קבועות, rate הוא הריבית לזמן שבין שתי הפקדות. הפקדה בכל רבעון: ריבית רבעונית. בעמודה בלי הפקדות: הריבית הנתונה, כמו שהיא.', 'left')],
      ['nper', 'מספר התקופות', MORE('מה סופרים?', 'בעמודה שיש בה הפקדות, nper סופר הפקדות. בעמודה של צבירה בלבד הוא סופר תקופות ריבית, באותה יחידה כמו rate.', 'left')],
      ['pmt', 'ההפקדה הקבועה, או 0', MORE('למה במינוס?', 'הפקדה היא כסף שיוצא מכם, ולכן היא שלילית. הסכום שתקבלו בסוף יוצא חיובי. זו מוסכמת הסימן של Excel.', 'left')],
      ['pv', 'סכום חד פעמי בתחילת העמודה', MORE('ובעמודה שנייה?', 'שם pv הוא ה-FV של העמודה הקודמת, בסימן הפוך: =-C6. הסכום שנצבר הוא שוב הפקדה, לתחילת המקטע הבא.', 'left up')],
      ['fv', XL('=FV(rate, nper, pmt, pv)'), MORE('לאיזה מועד?', 'למועד ההפקדה האחרונה של העמודה, או לסוף תקופת הצבירה שלה. ה-FV של העמודה האחרונה הוא התשובה.', 'left up')]]), cls='card')
  + '</div><div class="col">' + RELAY(2)
  + BAND('dg', 'כל עמודה היא רץ אחד במרוץ שליחים. היא מקבלת סכום ב-pv, מוסיפה לו ריבית והפקדות, ומוסרת את ה-FV לעמודה הבאה.', 3)
  + BAND('note', 'היום נפגוש שאלות עם שלוש וארבע עמודות. השיטה לא משתנה: רק מספר הרצים.', 4)
  + '</div></div>', kick='חלק 1 · המהות')

