   steps=[dict(cells={'C6': '=FV(C2,C3,C4,C5)'}, note=f'שלב 1: FV₂₀ = {nf(_a)}, בסוף הרבעון ה-20.'), dict(cells={'D5': '=-C6', 'D6': '=FV(D2,D3,D4,D5)'}, note=f'שלב 2: עוד 12 רבעונים בלי הפקדות. FV₃₂ = {nf(_b)}.')],
