   traps={'D6': [('=FV(D2,D3,0,D5)', 'גם בשנים 2 עד 4 ממשיכים להפקיד: pmt של −2,500.')]},
   steps=[dict(cells={'C6': '=FV(C2,C3,C4,C5)'}, note=f'שלב 1: FV₁₂ = {nf(_a)}, בסוף חודש 12.'), dict(cells={'D5': '=-C6', 'D6': '=FV(D2,D3,D4,D5)'}, note=f'שלב 2: FV₁₂ נכנס כ-pv, ועוד 36 הפקדות ב-0.5%. FV₄₈ = {nf(_b)}.')],
   note=[('tip', 'כל שינוי פותח עמודה. כאן השתנתה רק הריבית, ולכן ההפקדה ממשיכה גם בעמודה השנייה.', 1)],
